styles:
.page-post .post-tag { font-size: 13.5px; color: var(--red);}
.page-post .post-author { max-width: var(--post-w); margin: clamp(40px, 5vw, 64px) auto 0; padding: clamp(24px, 3vw, 36px); border: 1px solid var(--line); border-radius: var(--radius-lg); background: var(--bg-alt);}
.page-post .post-author__name { font-family: var(--font-display); font-weight: 700; font-size: 22px; color: var(--grey-900);}
.page-post .post-author__role { font-size: 15px; color: var(--grey-500); margin-top: 4px;}
.page-post .post-author__contact { font-size: 15px; color: var(--grey-700); margin-top: 14px; line-height: 1.8;}
.page-post .post-author__contact a { color: var(--red);}
